<script>
import { api } from "@/conf/api";
import Navbar from "../components/Navbar";
import Footer from "../components/footer.vue";
import draggable from 'vuedraggable'

export default {
    async beforeMount() {

        let usuario = JSON.parse(localStorage.getItem('usu'));
        this.id_empresa = usuario.id_empresa

        await this.buscarColunas()
        await this.buscarPendencias()

    },

    components: {
        Navbar,
        Footer,
        draggable
    },

    data() {
        return {

            wppnum: "",
            dialogAddCard: false,
            nomeNovaColuna: "",
            dialogDeleteCard: false,
            colunaSelecionada: null,
            posicao: 0,
            corNovaColuna: '',
            atendimentos: [],
            cardSelecionado: "",
            dialogEditarCard: false,
            id_empresa: "",
            kanban: []
        };
    },
    computed: {

    },

    methods: {
        abrirEditarCard(card) {
            this.cardSelecionado = { ...card } // clone
            this.dialogEditarCard = true
        },
        async buscarPendencias() {

            let res = await api.get(`/buscarPendencias/${this.id_empresa}`)

            const dados = res.data.dados

            // limpa cards
            this.kanban.forEach(coluna => {
                coluna.cards = []
            })

            dados.forEach(p => {

                let status = (p.status || "Novo").trim()

                const coluna = this.kanban.find(c => c.nome === status)

                if (coluna) {
                    p.cor = coluna.cor // 🔥 AQUI É A MÁGICA
                    coluna.cards.push(p)
                }

            })

        },

        async buscarColunas() {

            let res = await api.get(`/selectColuna/${this.id_empresa}`)
            console.log('mickey', res)
            console.log(res)
            this.kanban = res.data.dados.map(c => ({
                nome: c.nome,
                cor: c.cor,
                cards: []
            }))

        },

        async deletarColuna() {

            if (!this.colunaSelecionada) {
                alert("Selecione uma coluna")
                return
            }

            try {

                await api.post("/deletarColunaKanban", {
                    nome: this.colunaSelecionada,
                    idEmpresa: this.id_empresa
                })

                this.kanban = this.kanban.filter(
                    c => c.nome !== this.colunaSelecionada
                )

                this.dialogDeleteCard = false
                this.colunaSelecionada = null

            } catch (err) {

                console.log("Erro ao deletar coluna", err)

            }

        },

        async atualizarStatus(novoStatus, evt) {

            if (evt.added) {

                const pendencia = evt.added.element

                // 🔍 encontra a nova coluna
                const coluna = this.kanban.find(c => c.nome === novoStatus)

                if (coluna) {
                    pendencia.cor = coluna.cor // 🔥 ATUALIZA A COR NA HORA
                }

                try {

                    await api.post("/atualizarStatusPendencia", {
                        id: pendencia.id,
                        status: novoStatus
                    })

                    pendencia.status = novoStatus

                } catch (err) {
                    console.log("Erro ao atualizar status da pendência", err)
                }

            }

        },
        async deslogar() {

            this.$router.push("chat");

        },
        getStatusColor(element) {

            if (element.cor) return element.cor

            return 'grey'
        },

        getPrioridadeColor(p) {

            switch (p) {

                case "Alta":
                    return "red"

                case "Media":
                    return "orange"

                case "Baixa":
                    return "green"

                default:
                    return "grey"
            }

        },

        async criarColuna() {

            const nome = this.nomeNovaColuna?.trim()

            if (!nome) return

            // evita duplicada
            const existe = this.kanban.find(c => c.nome.toLowerCase() === nome.toLowerCase())

            if (existe) {
                alert("Essa coluna já existe")
                return
            }

            try {

                await api.post("/criarColunaKanban", {
                    nome: nome,
                    idEmpresa: this.id_empresa,
                    posicao: this.posicao,
                    cor: this.corNovaColuna // 🔥 AQUI
                })

                // adiciona no kanban local
                this.kanban.push({
                    nome: nome,
                    cards: []
                })

                this.nomeNovaColuna = ""
                this.dialogAddCard = false
                location.reload()


            } catch (err) {

                console.log("Erro ao criar coluna", err)

            }

        }

    },
};
</script>

